// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2012, "10-11", [{"author":"И. Иткин","question":"Какого слова не существует в русском литературном языке?","choices":["<em>сторонний</em>","<em>посторонний</em>","<em>тупосторонний</em>","<em>потусторонний</em>","все эти слова существуют."],"key":"В","review":["Начала похожих слов","Прочитай каждый вариант в привычном контексте: «сторонний наблюдатель», «посторонний звук», «потусторонний мир».","Эти три слова существуют. Слово «тупосторонний» не входит в литературный словарь."]},{"author":"Е. Муравенко","question":"<em>В аудиторию вошли две студентки. С ___________ студентками он уже был знаком.</em> Что нужно поставить вместо прочерка?","choices":["<em>обоями</em>","<em>обеями</em>","<em>обоими</em>","<em>обеими</em>","<em>обойми</em>."],"key":"Г","review":["Творительный от «обе»","«Студентки» — существительное женского рода. Поставь числительное «обе» в падеж, который требует «с».","«С кем?» — «с обеими студентками». В мужском роде было бы «с обоими студентами»."]},{"author":"И. Иткин","question":"Какое из этих слов почти никогда не пишется с большой буквы?","choices":["<em>аж</em>","<em>бы</em>","<em>ведь</em>","<em>где</em>","все эти слова достаточно часто пишутся с большой буквы."],"key":"Б","review":["Начало предложения","Подумай, какие слова могут открывать вопрос, восклицание или пояснение. Одно из них обычно примыкает к уже сказанному слову.","Частица «бы» обычно следует после другого слова: «я бы», «если бы». Поэтому она редко оказывается в позиции, где нужна прописная буква."]},{"author":"И. Иткин","question":"В каком слове нет суффикса <em>-н-</em>?","choices":["<em>вешний</em>","<em>летний</em>","<em>осенний</em>","<em>зимний</em>","суффикс <em>-н-</em> есть во всех этих словах."],"key":"А","review":["Суффикс в прилагательном","Сопоставь «летний» с «лето», «осенний» с «осень», «зимний» с «зима». Проверь, прибавляется ли «н».","В этих трёх словах выделяется суффикс «-н-». В «вешний» последовательность «вешн-» входит в корень."]},{"author":"А. Пиперски","question":"Какой из этих глаголов отличается от остальных ударением?","choices":["<em>обусловить</em>","<em>празднословить</em>","<em>прекословить</em>","<em>благословить</em>","<em>славословить.</em>"],"key":"Г","review":["Место ударения","Произнеси все глаголы и проверь, падает ли ударение на «о» корня или на конечное «и».","«Обусло́вить», «праздносло́вить», «прекосло́вить» и «славосло́вить» имеют ударение на корне. Выделяется «благослови́ть»."]},{"author":"И. Иткин и С. Переверзева","question":"К слову <em>оптимист</em> можно подобрать однокоренное абстрактное существительное с суффиксом -<em>изм</em>: <em>оптимизм</em>. К какому из следующих слов однокоренное существительное таким способом подобрать нельзя?","choices":["<em>буддист</em>","<em>гимназист</em>","<em>гуманист</em>","<em>фаталист</em>","ко всем можно."],"key":"Б","review":["Названия взглядов","Для каждого слова проверь, существует ли название учения или направления с тем же корнем и суффиксом «-изм».","Есть «буддизм», «гуманизм» и «фатализм». Гимназист — ученик гимназии, а общеупотребительного слова «гимназизм» нет."]},{"author":"Б. Иомдин","question":"Даны значения четырёх слов из языка хинди — одного из государственных языков Индии: ‘повязывать’, ‘учитель’, ‘лес’, ‘одно из воплощений божества’. Установите порядок слов, соответствующий порядку значений.","choices":["jangal, guru, bandhana, avatār","bandhana, guru, jangal, avatār","avatār, guru, jangal, bandhana","bandhana, avatār, jangal, guru","bandhana, guru, avatār, jangal"],"key":"Б","review":["Хинди и знакомые слова","Вспомни «гуру» как название учителя, «джунгли» как название леса и «аватар» в исходном религиозном смысле.","«Guru» — учитель, «jangal» — лес, «avatār» — воплощение божества. Тогда «bandhana» — повязывать, что даёт правильный порядок."]},{"author":"А. Сомин","question":"Антон сказал Саше: «Я хотел бы попросить тебя об одной услуге, если только это не пойдёт в _____ твоим делам». Какое слово мы пропустили?","choices":["<em>урон</em>","<em>угрозу</em>","<em>укор</em>","<em>ущерб</em>","<em>удар.</em>"],"key":"Г","review":["Пропуск в просьбе","Ищи устойчивое сочетание «в ... чему-либо» со значением вреда.","Говорят «пойти в ущерб делам». Это значит повредить делам или помешать им."]},{"author":"И. Рубанов","question":"В какой из пар (А)–(Г) слова не связаны по смыслу так, как в остальных?","choices":["<em>акт — контракт</em>","<em>атака — контратака</em>","<em>разведка — контрразведка</em>","<em>удар — контрудар</em>","во всех парах (А)–(Г) слова связаны по смыслу одинаково."],"key":"А","review":["Два смысла начала «контр»","В трёх парах добавление «контр-» даёт действие, направленное против названного первым словом.","Контратака, контрразведка и контрудар противостоят атаке, разведке и удару. «Контракт» означает договор и не связан с противодействием акту."]},{"author":"Л. Фёдорова","question":"<em>Беда</em>, <em>пот</em>, <em>пятница</em>. С каким числительным все эти слова употребляются в устойчивых выражениях и поговорках?","choices":["два","три","пять","семь","десять."],"key":"Г","review":["Число в трёх поговорках","Вспомни оборот о слишком частой перемене решений и поговорку о бедах и ответе.","Говорят «семь пятниц на неделе», «семь бед — один ответ», «семь потов сойдёт». Везде используется «семь»."]},{"author":"И. Иткин","question":"Какое из этих слов можно понять и как глагол совершенного, и как глагол несовершенного вида?","choices":["<em>побросать</em>","<em>покидать</em>","<em>пошвырять</em>","<em>повыбрасывать</em>","ни один из ответов (А)–(Г) не подходит."],"key":"Б","review":["Два вида у одной формы","Прочитай слово «покидать» с разными ударениями. Сравни, идёт ли речь об уходе или о бросках.","«Покида́ть дом» — несовершенный вид, есть процесс ухода. «Поки́дать мячи» — совершенный, то есть какое-то время покидать и закончить."]},{"author":"М. Руссо","question":"Слово <em>ластик</em> получилось в результате отбрасывания буквы ... .","choices":["<em>п</em>","<em>р</em>","<em>э</em>","<em>о</em>","<em>к</em>."],"key":"В","review":["Слово с потерянной буквой","Прибавь к «ластик» по одной начальной букве. Ищи старое обозначение материала, который может растягиваться.","Ластик назвали от слова «эластик». Начальная буква «э» отпала."]},{"author":"К. Гилярова","question":"Над одним магазином в Словении висит вывеска-реклама: NAHRBTNIKI. Что продаётся в этом магазине?","choices":["шляпы","сапоги","рюкзаки","наклейки","кровати."],"key":"В","review":["Вывеска в Словении","Сравни «hrbt» с русским «хребет». Какой предмет носят на спине?","«Nahrbtniki» буквально связывается с тем, что носят на спине. Это рюкзаки."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Какое слово не называет человека?","choices":["<em>выходец</em>","<em>иноходец</em>","<em>первопроходец</em>","<em>проходимец</em>","<em>мореход</em>."],"key":"Б","review":["Необычный способ ходьбы","Один вариант связан не со значением «ходить» у человека, а с особенным аллюром лошади.","«Иноходец» — лошадь, которая ходит иноходью, одновременно вынося ноги одной стороны. Остальные названия могут относиться к людям."]},{"author":"Е. Муравенко","question":"Даны обозначения действий и инструментов для их выполнения. В какой из пар соотношение между её членами не совсем такое, как в других парах?","choices":["<em>нарисовать картинку</em> — <em>карандаш</em>","<em>раскрасить картинку</em> — <em>фломастер</em>","<em>выделить предложение</em> — <em>маркер</em>","<em>начертить окружность</em> — <em>циркуль</em>","<em>начертить отрезок</em> — <em>линейка</em>."],"key":"Д","review":["Орудие для отрезка","Подумай, какие из предметов оставляют след на бумаге и какой задаёт форму, пока след оставляет другой инструмент.","Линейка направляет карандаш вдоль прямой, сама она не проводит линию. В других парах инструмент оставляет нужный след, включая циркуль с грифелем."]},{"author":"К. Гилярова","question":"О предмете постоянных разговоров, пересудов говорят: <em>при_ча во язы_х</em>. Заполните пропуски.","choices":["<em>т</em>, <em>це</em>","<em>т</em>, <em>ца</em>","<em>д</em>, <em>це</em>","<em>д</em>, <em>ца</em>","<em>т</em>, <em>тца.</em>"],"key":"А","review":["Пословичный оборот","Вспомни слово «притча» и старую форму «во языцех», где «языки» означают народы.","Нормативный оборот «притча во языцех» обозначает предмет общих разговоров. В пропусках стоят «т» и «це»."]},{"author":"И. Рубанов","question":"Одно из интернет-изданий пишет: «Франция добилась внесения круассанов в список продуктов с охраняемым географическим статусом. Уже через полгода их выпечка в других странах Евросоюза станет незаконной».\nКакие из трёх следующих утверждений справедливы в такой ситуации?\n1) Производство круассанов будет ограничено на территории Франции.\n2) Производство круассанов в Евросоюзе будет ограничено территорией Франции.\n3) Производство круассанов будет ограничено вне территории Франции.","choices":["только 3","только 1 и 2","только 1 и 3","только 2 и 3","все."],"key":"Г","review":["Границы производства","Сравни «ограничено на территории» с «ограничено территорией». Одно говорит, где действует ограничение, другое — где разрешают производство.","В описанной ситуации выпекать круассаны по-прежнему можно во Франции. Производство в ЕС ограничивается Францией, а запрет действует вне неё. Верны 2 и 3."]},{"author":"Е. Муравенко","question":"Какое слово отличается от остальных склонением?","choices":["<em>сосед</em>","<em>артист</em>","<em>актёр</em>","<em>спортсмен</em>","<em>матрос</em>."],"key":"А","review":["Множественное число слов","Сравни множественные формы всех существительных. Проверь, какое слово меняет конец основы и тип окончания.","«Сосед» даёт «соседи», «соседей». У остальных слов формы «артисты», «актёры», «спортсмены», «матросы» и родительные на «-ов»."]},{"author":"И. Иткин","question":"Какая из этих последовательностей слов может с большей вероятностью встретиться в написанном без ошибок тексте на русском языке?","choices":["<em>...а Приключения...</em>","<em>...и Приключения...</em>","<em>...или Приключения...</em>","<em>...но Приключения...</em>","ни одну из этих последовательностей встретить в правильно написанном тексте практически невозможно."],"key":"В","review":["Прописная буква после союза","Вспомни двойные заглавия книг. Какое слово вводит второй вариант названия?","В названии вроде «Робинзон Крузо, или Приключения на необитаемом острове» после «или» начинается второй заголовок. Поэтому «Приключения» пишут с прописной."]},{"author":"Л. Фёдорова","question":"Где по современным правилам следует поставить запятые?\n<em>Мороз-воевода дозором\nОбходит владенья свои.\nГлядит — хорошо ли метели</em> (1)\n<em>Лесные тропы занесли</em> (2)\n<em>И нет ли</em> (3) <em>где трещины</em> (4) <em>щели</em> (5)\n<em>И нет ли</em> (6) <em>где голой земли.</em>\n(Н. А. Некрасов)","choices":["везде","только в 2, 4, 5","только в 2, 4","только в 4, 5","только в 5, 6."],"key":"Б","review":["Запятые в строках Некрасова","Выдели три вопросительные части после «глядит». Отдельно проверь однородный ряд «трещины, щели».","Между вопросительными частями с повторяющимся «и» нужны запятые в местах 2 и 5. Между «трещины» и «щели» нужна запятая на месте 4."]},{"author":"М. Руссо","question":"Из какого материала было платье у жеманной и изнеженной девицы из романа Н. Г. Помяловского «Мещанское счастье»?","choices":["из шёлка","из сатина","из ситца","из кисеи","из атласа."],"key":"Г","review":["Ткань в романе","Вспомни выражение о чрезмерно изнеженной девушке. В нём есть прилагательное от названия тонкой ткани.","Таких девушек называют «кисейными барышнями». Платье в романе было из кисеи."]},{"author":"Е. Муравенко и А. Сомин","question":"Саша съездила в Тарту и в Хельсинки, а потом показывала друзьям ______________ фотографии. Что в соответствии с современной литературной нормой следует вставить вместо прочерка?","choices":["тартуские и хельсинские","тартуские и хельсинкские","тартусские и хельсиновские","тартусские и хельсинские","тартусские и хельсинкские."],"key":"Б","review":["Прилагательные от городов","Отдели основу названий городов и сравни три предполагаемых варианта каждого прилагательного.","Словарные формы — «тартуский» от Тарту и «хельсинкский» от Хельсинки. Поэтому «тартуские и хельсинкские фотографии»."]},{"author":"П. Аркадьев","question":"Какой из глаголов исторически содержал (а по мнению ряда лингвистов, и сейчас содержит) приставку <em>до</em>-?","choices":["<em>предотвратить</em>","<em>подобрать</em>","<em>надорвать</em>","<em>раздобыть</em>","<em>надоить</em>."],"key":"Г","review":["Старая приставка «до-»","Отыщи глагол, который можно связать со словом «добыть». Попробуй снять внешнюю приставку.","В «раздобыть» есть «раз-» и основа «добыть», исторически «до-быть». В «надорвать» сочетание «до» относится к приставке «надо-»."]},{"author":"П. Аркадьев","question":"В каком из предложений 1–4, встреченных в реальных текстах, нет ошибки в употреблении подчёркнутых слов?\n1. Что касается власти — даже одна подпись может обладать невероятной силой, если мы <u>обличены</u> властью.\n2. Лица, <u>обличённые</u> ответственностью в экономике, несут также и политическую ответственность.\n3. Каждое преступление должно быть расследовано, преступник <u>изоблечён</u>, пойман и осуждён.\n4. Отказ был <u>облечён</u> в вежливую форму.","choices":["в 1, 2 и 3","только в 1 и 2","в 3 и 4","только в 4","только в 2 и 3."],"key":"Г","review":["Похожие глаголы и значения","Различи «облечь», то есть наделить или придать форму, «обличить» и «изобличить», то есть раскрыть вину.","В 1 и 2 нужно «облечены» и «облечённые», в 3 — «изобличён». Только 4 употребляет «облечён» правильно: отказу придали вежливую форму."]},{"author":"Б. Иомдин","question":"Шуточный вариант этого выражения кончается словами …<em>вечером разогнём</em>. А как оно заканчивается на самом деле?","choices":["…<em>вечером стулья</em>","…<em>весело запоём</em>","…<em>не сыщешь</em>","…<em>не догонишь</em>","…<em>с утра искал</em>."],"key":"В","review":["Конец знакомого выражения","«Вечером разогнём» шутливо продолжает оборот о настойчивом и обычно безрезультатном поиске.","Оригинал — «днём с огнём не сыщешь». Его употребляют о том, что практически невозможно найти."]},{"author":"А. Пиперски","question":"В романе В. Набокова «Дар» рассказчик так отзывается о стихах одного из персонажей, которые он считает плохими: «„…“ занимал три места в стихотворной строке, заплатив лишь за два». Какое слово пропущено?","choices":["<em>январь</em>","<em>март</em>","<em>апрель</em>","<em>август</em>","<em>октябрь</em>."],"key":"Д","review":["Сколько мест в строке","Сравни число слогов и соседние согласные в названиях месяцев. Одна группа согласных делает двусложное слово особенно тяжёлым для стиха.","Набоков пишет об «октябре». В слове два слога, но заключительное сочетание «брь» утяжеляет его, и рассказчик шутит о третьем занятом месте."]},{"author":"Б. Иомдин","question":"В книге В. Долопчева «Опыт словаря неправильностей в русской разговорной речи» (Варшава, 1909) высказана такая гипотеза: <em>«Форма ___________ есть изменение первоначальной: ___________ , выражающей сознание говорящего, что ему оказано добро»</em>. Какие слова мы пропустили?","choices":["<em>благодарю, благо дарю</em>","<em>благодарствуйте, благодарствуете</em>","<em>пожалуйста, пожалуйте</em>","<em>спасибо, спаси Бог</em>","<em>будьте добры, вы так добры</em>."],"key":"Б","review":["Форма в старом словаре","Сравни варианты по длине и по буквам. Долопчев считал, что исходная форма описывала совершаемое собеседником действие.","В словаре речь о «благодарствуйте» и форме «благодарствуете». Именно эти слова автор сопоставил в процитированной статье."]},{"author":"С. Переверзева","question":"Какое из этих слов содержало гласный звук, впоследствии выпавший?","choices":["<em>правда</em>","<em>уста</em>","<em>утро</em>","<em>черта</em>","<em>клятва</em>."],"key":"А","review":["Исчезнувшая гласная","Вспомни, что «ь» в древнерусском языке мог обозначать короткий гласный звук, который позднее исчезал.","«Правда» восходит к форме «правьда». Между «в» и «д» был краткий гласный, и он выпал."]},{"author":"А. Пиперски","question":"Вспомните названия последних месяцев года и скажите: какой месяц в республиканском Риме назывался <em>квинтилий</em>?","choices":["<em>апрель</em>","<em>май</em>","<em>июнь</em>","<em>июль</em>","<em>август</em>."],"key":"Г","review":["Месяц в римском календаре","«Квинтилий» связан со словом «пятый». В старом римском счёте месяцев первым шёл март.","Март, апрель, май, июнь, июль — пять месяцев. Квинтилий позднее получил название в честь Юлия Цезаря."]},{"author":"Е. Муравенко","question":"Чаще всего слово <em>год</em> употребляется с предлогом <em>в</em> в сочетании <em>в</em> … <em>году</em>: <em>в прошлом году</em>, <em>в 2005 году</em> и т. п. А в каком сочетании существительное <em>год</em> не встречается?","choices":["<em>в</em> … <em>год</em>","<em>на</em> … <em>год</em>","<em>на</em> … <em>годе</em>","<em>на</em> … <em>году</em>","все указанные в (А)–(Г) варианты возможны."],"key":"Д","review":["«Год» с двумя предлогами","Подставь слова «тот», «следующий», «этом» и «пятом». Проверь, всегда ли речь идёт о времени или можно говорить о теме.","Возможны «в тот год», «на следующий год», «остановимся на этом годе» и «на пятом году жизни». Все четыре сочетания существуют."]}], {"year":2012,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2012.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
